import json
from pathlib import Path
d=json.loads(Path("/root/.pm2/dump.pm2").read_text())
out={"count":len(d),"items":[]}
for a in d:
 e=a.get("pm2_env") or {}
 fields=("name","pm_cwd","pm_exec_path","exec_interpreter","pm_out_log_path","pm_err_log_path","args")
 out["items"].append({"top":{k:a.get(k) for k in fields},"nested":{k:e.get(k) for k in fields},"nested_exists":bool(e)})
print(json.dumps(out,sort_keys=True))
